@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

:root {
  --primary: #000000;
  --primary-hover: #333333;
  --accent-lime: #E6FF32;
  --accent-lime-hover: #D4ED1A;
  --accent-burgundy: #7F2A23;
  --bg-color: #FFFFFF;
  --bg-light: #F8FAFC;
  --bg-muted: #F1F5F9;
  --text-main: #0F172A;
  --text-muted: #475569;
  --border-color: #E2E8F0;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-normal: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-color);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--primary);
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: -0.02em;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--text-muted);
}

/* Typography Scale */
h1 { font-size: clamp(2.5rem, 5vw, 4rem); margin-bottom: 1.5rem; font-weight: 800; }
h2 { font-size: clamp(2rem, 4vw, 3rem); margin-bottom: 1.5rem; }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); margin-bottom: 1rem; }
h4 { font-size: 1.25rem; margin-bottom: 0.75rem; }
p { margin-bottom: 1rem; color: var(--text-muted); }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }

/* Layout & Containers */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 6rem 0;
}
.section-sm {
  padding: 4rem 0;
}
.bg-light { background-color: var(--bg-light); }
.bg-dark { background-color: var(--primary); color: white; }
.bg-dark h1, .bg-dark h2, .bg-dark h3, .bg-dark h4 { color: white; }
.bg-dark p { color: #CBD5E1; }
.bg-lime { background-color: var(--accent-lime); color: var(--primary); }
.bg-burgundy { background-color: var(--accent-burgundy); color: white; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 2px solid transparent;
  text-align: center;
  font-family: var(--font-heading);
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}
.btn-primary:hover {
  background-color: var(--primary-hover);
  color: white;
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background-color: var(--accent-lime);
  color: var(--primary);
}
.btn-accent:hover {
  background-color: var(--accent-lime-hover);
  color: var(--primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--primary);
  color: var(--primary);
}
.btn-outline:hover {
  background-color: var(--primary);
  color: white;
}

/* Header & Nav */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.nav-link {
  font-weight: 500;
  color: var(--text-main);
  position: relative;
}
.nav-link::after {
  content: '';
  position: absolute;
  width: 0;
  height: 2px;
  bottom: -4px;
  left: 0;
  background-color: var(--accent-lime);
  transition: width var(--transition-fast);
}
.nav-link:hover::after {
  width: 100%;
}
.nav-link:hover {
  color: var(--primary);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--primary);
}

/* Hero Section */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
  overflow: hidden;
  position: relative;
}
.hero-content {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}
.hero-cta {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-top: 2.5rem;
}

/* Tabs */
.tabs-wrapper {
  margin-top: 4rem;
}
.tab-buttons {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}
.tab-btn {
  background: var(--bg-muted);
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
  font-family: var(--font-body);
}
.tab-btn.active {
  background: var(--primary);
  color: white;
  box-shadow: var(--shadow-md);
}
.tab-content {
  display: none;
  animation: fadeIn var(--transition-normal);
}
.tab-content.active {
  display: block;
}

/* Tabbed Image/Preview area */
.preview-window {
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  border: 1px solid var(--border-color);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-light);
  position: relative;
}
.preview-header {
  height: 40px;
  background: var(--bg-muted);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  padding: 0 1rem;
  gap: 0.5rem;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #CBD5E1;
}
.dot:nth-child(1) { background: #EF4444; }
.dot:nth-child(2) { background: #F59E0B; }
.dot:nth-child(3) { background: #10B981; }

.preview-body {
  margin-top: 40px;
  width: 100%;
  height: calc(100% - 40px);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-muted);
  padding: 2rem;
  text-align: center;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 3rem; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* Cards */
.card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-normal);
  display: flex;
  flex-direction: column;
  height: 100%;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--accent-lime);
}
.card-icon {
  width: 48px;
  height: 48px;
  background: var(--bg-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--primary);
}
.card-title {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

/* Stats Bar */
.stats-bar {
  background: var(--primary);
  color: white;
  padding: 3rem 0;
  border-top: 4px solid var(--accent-lime);
}
.stat-item {
  text-align: center;
}
.stat-value {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--accent-lime);
  margin-bottom: 0.5rem;
}
.stat-label {
  font-size: 1.125rem;
  font-weight: 500;
  color: #E2E8F0;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border-color);
  padding: 1.5rem 0;
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  padding: 0;
  font-family: var(--font-heading);
}
.faq-icon {
  width: 24px;
  height: 24px;
  transition: transform var(--transition-fast);
}
.faq-item.active .faq-icon {
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-normal);
  color: var(--text-muted);
}
.faq-item.active .faq-answer {
  max-height: 500px;
}
.faq-answer-inner {
  padding-top: 1rem;
}

/* Testimonial Carousel */
.carousel-container {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: white;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border-color);
}
.carousel-track {
  display: flex;
  transition: transform var(--transition-normal);
}
.carousel-slide {
  min-width: 100%;
  padding: 4rem;
  text-align: center;
}
.testimonial-quote {
  font-size: 1.5rem;
  font-weight: 500;
  color: var(--primary);
  margin-bottom: 2rem;
  font-style: italic;
}
.testimonial-author {
  font-weight: 700;
  color: var(--primary);
}
.testimonial-brand {
  color: var(--text-muted);
  font-size: 0.875rem;
}
.carousel-controls {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  transform: translateY(-50%);
  display: flex;
  justify-content: space-between;
  padding: 0 1rem;
  pointer-events: none;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: white;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  pointer-events: auto;
  transition: all var(--transition-fast);
  color: var(--primary);
}
.carousel-btn:hover {
  background: var(--primary);
  color: white;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 2rem;
  align-items: center;
  justify-items: center;
  opacity: 0.7;
}
.integration-item {
  font-weight: 600;
  font-size: 1.125rem;
  color: var(--text-muted);
  transition: all var(--transition-fast);
}
.integration-item:hover {
  opacity: 1;
  color: var(--primary);
  transform: scale(1.05);
}

/* Vertical feature tabs (Why Choose Us) */
.vertical-tabs {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 3rem;
  align-items: start;
}
.v-tab-buttons {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.v-tab-btn {
  text-align: left;
  padding: 1rem 1.5rem;
  background: transparent;
  border: none;
  border-left: 3px solid transparent;
  font-weight: 600;
  font-size: 1.125rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
  font-family: var(--font-heading);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
}
.v-tab-btn:hover {
  background: var(--bg-muted);
  color: var(--primary);
}
.v-tab-btn.active {
  border-left-color: var(--accent-lime);
  color: var(--primary);
  background: var(--bg-muted);
}
.v-tab-content {
  display: none;
  animation: fadeIn var(--transition-normal);
  background: white;
  padding: 3rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
}
.v-tab-content.active {
  display: block;
}
.feature-list {
  list-style: none;
  margin-top: 1.5rem;
}
.feature-list li {
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.feature-list li::before {
  content: '✓';
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: var(--accent-lime);
  color: var(--primary);
  border-radius: 50%;
  font-size: 0.75rem;
  font-weight: 800;
}

/* Footer */
.footer {
  background: var(--primary);
  color: white;
  padding: 5rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}
.footer-col h4 {
  color: white;
  margin-bottom: 1.5rem;
}
.footer-links {
  list-style: none;
}
.footer-links li {
  margin-bottom: 0.75rem;
}
.footer-links a {
  color: #94A3B8;
}
.footer-links a:hover {
  color: white;
}
.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #94A3B8;
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  background: var(--primary);
  color: white;
  border-radius: var(--radius-lg);
  padding: 4rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: var(--accent-lime);
  filter: blur(100px);
  opacity: 0.2;
  border-radius: 50%;
}
.cta-banner::after {
  content: '';
  position: absolute;
  bottom: -50%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: var(--accent-burgundy);
  filter: blur(100px);
  opacity: 0.3;
  border-radius: 50%;
}
.cta-banner-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
  margin: 0 auto;
}
.cta-banner h2 {
  color: white;
}

/* Utility */
.text-center { text-align: center; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-12 { margin-bottom: 3rem; }
.text-accent { color: var(--accent-lime); }
.text-burgundy { color: var(--accent-burgundy); }

/* Responsive */
@media (max-width: 1024px) {
  .vertical-tabs {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .v-tab-buttons {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 1rem;
  }
  .v-tab-btn {
    border-left: none;
    border-bottom: 3px solid transparent;
    border-radius: var(--radius-md) var(--radius-md) 0 0;
    white-space: nowrap;
  }
  .v-tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--accent-lime);
  }
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .header .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .hero { padding: 5rem 0 3rem; }
  .section { padding: 4rem 0; }
  .carousel-slide { padding: 2rem; }
  .footer-grid { grid-template-columns: 1fr; }

  /* Mobile menu active state */
  .nav-links.active {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background: white;
    padding: 2rem;
    box-shadow: var(--shadow-md);
    border-bottom: 1px solid var(--border-color);
  }
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Menu
  const menuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');
  if (menuBtn && navLinks) {
    menuBtn.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });
  }

  // Horizontal Tabs (Hero section)
  const tabButtons = document.querySelectorAll('.tab-btn');
  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // Find parent context
      const wrapper = btn.closest('.tabs-wrapper');
      if (!wrapper) return;

      const target = btn.getAttribute('data-target');

      // Reset active states
      wrapper.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      wrapper.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));

      // Set active
      btn.classList.add('active');
      const content = wrapper.querySelector(target);
      if (content) content.classList.add('active');
    });
  });

  // Vertical Tabs (Why Choose Us)
  const vTabButtons = document.querySelectorAll('.v-tab-btn');
  vTabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const wrapper = btn.closest('.vertical-tabs');
      if (!wrapper) return;

      const target = btn.getAttribute('data-target');

      // Reset active states
      wrapper.querySelectorAll('.v-tab-btn').forEach(b => b.classList.remove('active'));
      wrapper.querySelectorAll('.v-tab-content').forEach(c => c.classList.remove('active'));

      // Set active
      btn.classList.add('active');
      const content = wrapper.querySelector(target);
      if (content) content.classList.add('active');
    });
  });

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (!question) return;

    question.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all others
      faqItems.forEach(faq => faq.classList.remove('active'));

      // Toggle current
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Carousels
  const carousels = document.querySelectorAll('.carousel-container');
  carousels.forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const btnPrev = carousel.querySelector('.carousel-prev');
    const btnNext = carousel.querySelector('.carousel-next');

    if (!track || slides.length === 0) return;

    let currentIndex = 0;

    const updateCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    if (btnPrev) {
      btnPrev.addEventListener('click', () => {
        currentIndex = (currentIndex > 0) ? currentIndex - 1 : slides.length - 1;
        updateCarousel();
      });
    }

    if (btnNext) {
      btnNext.addEventListener('click', () => {
        currentIndex = (currentIndex < slides.length - 1) ? currentIndex + 1 : 0;
        updateCarousel();
      });
    }
  });

  // Simple accordion for Courses Demo
  const demoToggle = document.querySelector('.demo-toggle');
  if (demoToggle) {
    demoToggle.addEventListener('click', () => {
      const content = document.querySelector('.demo-content');
      if (content) {
        content.classList.toggle('active');
        if (content.style.maxHeight) {
          content.style.maxHeight = null;
        } else {
          content.style.maxHeight = content.scrollHeight + "px";
        }
      }
    });
  }
});
